from netmiko import ConnectHandler

ROUTERS = {
    "HQ": "192.168.122.6",
    "Branch1": "192.168.122.5",
    "Branch2": "192.168.122.7",
}

for name, ip in ROUTERS.items():
    print(f"\n===== {name} =====")
    dev = {"device_type": "vyos", "host": ip, "username": "vyos", "password": "test"}
    c = ConnectHandler(**dev)
    for cmd in ["show interfaces", "show ip ospf neighbor", "show ip route ospf",
                "show configuration commands | grep ospf"]:
        print(f"\n--- {cmd} ---")
        print(c.send_command(cmd, read_timeout=30))
    c.disconnect()

